import{_ as a,o as e,c as r,ai as n}from"./chunks/framework.XEs52zTF.js";const u=JSON.parse('{"title":"证明它确实能工作","description":"","frontmatter":{"title":"证明它确实能工作","chapterId":"chapter21","prev":{"text":"按里程碑完成项目","link":"/chapter20"},"next":{"text":"扩展你的语言","link":"/chapter22"}},"headers":[],"relativePath":"chapter21.md","filePath":"chapter21.md"}'),o={name:"chapter21.md"};function d(i,t,p,s,l,h){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="_21-测试、差分、模糊测试与可信编译" tabindex="-1">21 测试、差分、模糊测试与可信编译 <a class="header-anchor" href="#_21-测试、差分、模糊测试与可信编译" aria-label="Permalink to &quot;21 测试、差分、模糊测试与可信编译&quot;">​</a></h1><h2 id="学习目标与前置知识" tabindex="-1">学习目标与前置知识 <a class="header-anchor" href="#学习目标与前置知识" aria-label="Permalink to &quot;学习目标与前置知识&quot;">​</a></h2><p>前置是能够独立构建和运行第 20 章工程。本章属于主线验证与进阶测试路线：已有脚本覆盖 VM、静态错误、运行时错误和 C++ 目标；随机生成器、自动缩减器与形式验证属于可以继续完成的扩展。</p><p>你要学会区分编译器崩溃、错误接受、错误拒绝、错误代码与资源超限，并知道一个可靠测试结果必须比较什么。测试通过增加信心，但不等于已证明全部输入正确。</p><h2 id="先建立测试分类" tabindex="-1">先建立测试分类 <a class="header-anchor" href="#先建立测试分类" aria-label="Permalink to &quot;先建立测试分类&quot;">​</a></h2><p>正例验证合法程序的输出与退出状态。负例验证非法程序在正确阶段拒绝，并带合理位置。运行时错误例验证除零、溢出、深度和预算错误受控结束。结构例验证 token、AST 与字节码的关键关系；不必把容易变化的地址编号全部固定死。</p><table tabindex="0"><thead><tr><th>类别</th><th>示例</th><th>核对内容</th></tr></thead><tbody><tr><td>词法</td><td>非法字符、关键字边界、CRLF</td><td>token 或词法错误位置</td></tr><tr><td>语法</td><td>缺分号、缺括号、错误表达式</td><td>拒绝且定位接近问题</td></tr><tr><td>语义</td><td>bool 加 int、名字不存在</td><td>执行前拒绝</td></tr><tr><td>执行</td><td>减法、递归、遮蔽、短路</td><td>打印序列与状态</td></tr><tr><td>保护</td><td>无限循环、过深嵌套</td><td>受控诊断，无宿主崩溃</td></tr></tbody></table><p>测试退出码时不要把 Sprout main 的返回值误当成宿主退出码：当前主线正常执行返回 0，语言 main 的数值结果被忽略。LLVM 直接返回 42 的实验是另一条独立模块实验，不能混用其约定。</p><h2 id="运行已有回归检查" tabindex="-1">运行已有回归检查 <a class="header-anchor" href="#运行已有回归检查" aria-label="Permalink to &quot;运行已有回归检查&quot;">​</a></h2><p>在 compiler 目录构建后运行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python tests/run_tests.py ./sprout</span></span>
<span class="line"><span>python tests/run_tests.py ./sprout --native g++</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Windows 可把 ./sprout 换成 <code>./sprout.exe</code>。第二条还会编译生成目标并比较多个 C++ 标准模式。若工具不可用，应该明确报告缺少哪个工具，不能把没有运行的检查算成通过。修改代码后先跑受影响类别，再跑完整回归，避免每次都用人工操作替代稳定测试。</p><h2 id="差分测试-两条路线互相检查" tabindex="-1">差分测试：两条路线互相检查 <a class="header-anchor" href="#差分测试-两条路线互相检查" aria-label="Permalink to &quot;差分测试：两条路线互相检查&quot;">​</a></h2><p>同一个确定性的源程序，分别通过 VM 与生成 C++ 的本机程序执行，比较标准输出、错误类别和成功/失败状态。两者不同就有问题，但仅凭不同还不能确定哪条路线错，需要回到规格或第三个参考模型。</p><p>两条后端可能共享 Checker、算术辅助规则或 AST，所以一致也不意味着绝对正确：共同 bug 不会被差分发现。可以为小表达式写独立数学模型，用 Python 大整数计算后显式检查 int32 范围，减少共享实现。</p><p>资源上限是一个例外边界：VM 按字节码计数，目标程序按检查点计数，接近预算时不承诺在同一步停止。差分样例应远离保护上限，或只比较“受控拒绝”，不要硬要求错误文本和行号完全相同。</p><h2 id="随机生成合法程序" tabindex="-1">随机生成合法程序 <a class="header-anchor" href="#随机生成合法程序" aria-label="Permalink to &quot;随机生成合法程序&quot;">​</a></h2><p>纯随机字节适合找词法和解析器崩溃；要找错误代码，更有效的是根据文法和类型生成合法 AST，再打印成源码。生成 int 表达式时只选 int 运算，生成 bool 时选比较、逻辑或 bool 字面量。维护可用变量表，避免随机产生未声明名字。</p><p>限定深度、数值范围与循环次数，记录随机种子，使失败可重现。第一版只生成纯表达式，之后逐步加局部变量、分支、函数和有限循环。除零与溢出可以作为单独负例类别；对正常结果的差分测试应避免未定义或未约定行为。</p><p>本地 Csmith 论文的关键启发正是：测试程序需要明确含义，否则多个结果未必意味着编译器错。不能把随机 C++ 中未规定的实参顺序直接当作 Sprout 的标准答案。</p><h2 id="变形测试与缩减" tabindex="-1">变形测试与缩减 <a class="header-anchor" href="#变形测试与缩减" aria-label="Permalink to &quot;变形测试与缩减&quot;">​</a></h2><p>没有参考答案时，可以使用应当保持行为的变形：重命名不冲突的局部变量、加入多余括号、用内层独立块包住不逃逸的语句。这些变形仍有前提。例如随意交换两条赋值可能改变依赖；把 x 改写为 <code>(x+1)-1</code> 在检查型整数下可能新增溢出。</p><p>发现失败后缩减程序：删除函数、删除语句、替换子表达式、减少常量，每次保留原来的失败性质。失败性质应定义清楚，例如“VM 与目标输出不同”，而不是“程序报了某个错”。否则缩减器可能把错误代码问题缩成一个毫不相关的语法错误。</p><p>最小复现应附语言版本、工具版本、构建选项、源程序、实际结果、预期结果和稳定复现命令。修复后把它加入测试，才算真正关闭问题。</p><h2 id="编译器本身的安全与健壮性" tabindex="-1">编译器本身的安全与健壮性 <a class="header-anchor" href="#编译器本身的安全与健壮性" aria-label="Permalink to &quot;编译器本身的安全与健壮性&quot;">​</a></h2><p>源码是不可信输入：超长数字、深括号、长二元链、超大文件、CRLF、注释结尾都值得覆盖。对输入大小、递归深度与 AST 高度分别设限，因为长左结合链即使解析递归不深，也可能生成很深的树。</p><p>使用地址/未定义行为检测工具可帮助发现宿主越界与悬垂引用，但支持情况依赖工具链。例如可在支持的 Clang/GCC 环境启用相应 sanitizer 后运行回归。内存检测发现的是编译器实现问题，不等于替代源语言的运行时检查。</p><h2 id="从测试走向证明与翻译验证" tabindex="-1">从测试走向证明与翻译验证 <a class="header-anchor" href="#从测试走向证明与翻译验证" aria-label="Permalink to &quot;从测试走向证明与翻译验证&quot;">​</a></h2><p>形式验证先为源与目标定义行为，再证明每个 pass 保持关系；翻译验证则对某一次编译的输入/输出检查等价或相容。一个较小入门项目是证明“纯算术表达式编译到栈机后，最终栈顶等于表达式求值”，使用结构归纳即可开始。</p><p>测试与证明可以互补。证明依赖规格和可信边界，解析、链接与外部运行时是否被覆盖必须明确；测试可以覆盖未形式化的边界与工具集成。不要把“用了证明助手”当作整个发布链都自动可信。</p><h2 id="练习、答案与验收" tabindex="-1">练习、答案与验收 <a class="header-anchor" href="#练习、答案与验收" aria-label="Permalink to &quot;练习、答案与验收&quot;">​</a></h2><p>设计十个正常例、十个静态负例、五个运行错误例；为每个写出类别与预期。再为纯表达式随机生成器设定固定种子，对 VM、本机路径和独立模型比较 100 个小样例。</p><details><summary>参考答案</summary><p>正常例应分散覆盖优先级、左结合、遮蔽、参数次序、前向调用、循环和短路。负例要有缺符号、名字错误、类型不符、漏返回；运行错误要覆盖边界溢出与除零，不能全部是同一类。随机失败应能凭种子复现并缩成更短程序。验收需保存测试命令与实际结果，未运行的环境应列为未验证。</p></details><h2 id="来源与后续" tabindex="-1">来源与后续 <a class="header-anchor" href="#来源与后续" aria-label="Permalink to &quot;来源与后续&quot;">​</a></h2><p>已读本地 <code>compilers-papers-we-love/testing/PLDI2011 Finding and Understanding Bugs in C Compilers.pdf</code> 第 1—2 页，以及 <code>compilers-testing/CACM2008 Formal Verification of a Realistic Compiler.pdf</code> 第 1—3 页。<a href="https://llvm.org/docs/TestingGuide.html" target="_blank" rel="noreferrer">LLVM 测试指南</a> 和 <a href="https://compcert.org/" target="_blank" rel="noreferrer">CompCert 官方项目</a> 可作进一步阅读。下一章规划如何有秩序地扩展语言与研究主题。</p>`,35)])])}const b=a(o,[["render",d]]);export{u as __pageData,b as default};
